print("Output with only rows 14-17 shifting (earliest wins):")
for pos in sorted(output):
    if output[pos] not in (2, 3):
        print(f"  {pos}: {output[pos]}")

# Build grid
final = [[2]*7 for _ in range(20)]
for r in range(20):
    for c in range(7):
        if r in green_rows:
            final[r][c] = 3
        elif (r, c) in output:
            final[r][c] = output[(r, c)]

print("\nFinal grid:")
for r in range(20):
    print(f"Row {r}: {final[r]}")

print(f"\nRow 14: {final[14]}")
print(f"Row 18: {final[18]}")
print(f"Row 19: {final[19]}")
